1	export interface Customer {
2	  readonly yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  readonly type: string;
7	  readonly cursed?: boolean;
8	  readonly enchantment?: number;
9	}
10	
11	const PROCESSING_FEE = 5;
12	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
13	const CURSE_SURCHARGE_RATE = 0.5;
14	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
15	const HIGH_ENCHANTMENT_LEVEL = 5;
16	
17	const MAIN_ITEM_BASE_PREMIUM_PRICE_LIST: Readonly<Record<string, number>> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	};
23	
24	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
25	const COMPONENT_BASE_PREMIUM = 25;
26	const ALIKE_COMPONENTS_PER_BLOCK = 3;
27	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
28	
29	function isComponent(item: Item): boolean {
30	  return COMPONENT_TYPES.includes(item.type);
31	}
32	
33	function mainItemBasePremiumOf(item: Item): number {
34	  return MAIN_ITEM_BASE_PREMIUM_PRICE_LIST[item.type] ?? 0;
35	}
36	
37	// "Alike" means the same item type, not the same family: 2 runes + 1 moonstone
38	// form no block.
39	function countAlikeComponents(components: readonly Item[]): Map<string, number> {
40	  const counts = new Map<string, number>();
41	  for (const component of components) {
42	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
43	  }
44	  return counts;
45	}
46	
47	function alikeComponentsBasePremiumOf(alikeCount: number): number {
48	  if (alikeCount === ALIKE_COMPONENTS_PER_BLOCK) {
49	    return COMPONENT_BLOCK_BASE_PREMIUM;
50	  }
51	  return alikeCount * COMPONENT_BASE_PREMIUM;
52	}
53	
54	function componentsBasePremiumOf(components: readonly Item[]): number {
55	  let total = 0;
56	  for (const alikeCount of countAlikeComponents(components).values()) {
57	    total += alikeComponentsBasePremiumOf(alikeCount);
58	  }
59	  return total;
60	}
61	
62	function isCursed(item: Item): boolean {
63	  return item.cursed === true;
64	}
65	
66	function isHighlyEnchanted(item: Item): boolean {
67	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
68	}
69	
70	function itemSpecificSurchargesOn(item: Item, itemBasePremium: number): number {
71	  const curse = isCursed(item) ? itemBasePremium * CURSE_SURCHARGE_RATE : 0;
72	  const highEnchantment = isHighlyEnchanted(item)
73	    ? itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
74	    : 0;
75	  return curse + highEnchantment;
76	}
77	
78	function mainItemPremiumOf(mainItem: Item): number {
79	  const itemBasePremium = mainItemBasePremiumOf(mainItem);
80	  return itemBasePremium + itemSpecificSurchargesOn(mainItem, itemBasePremium);
81	}
82	
83	function mainItemsPremiumOf(mainItems: readonly Item[]): number {
84	  return mainItems.reduce((sum, mainItem) => sum + mainItemPremiumOf(mainItem), 0);
85	}
86	
87	// Only main items carry item-specific surcharges: components have no curse flag,
88	// enchantment level, or material in the MHPCO item model.
89	function insuredItemsPremiumOf(items: readonly Item[]): number {
90	  return (
91	    mainItemsPremiumOf(items.filter((item) => !isComponent(item))) +
92	    componentsBasePremiumOf(items.filter(isComponent))
93	  );
94	}
95	
96	function firstInsuranceSurchargeOn(insuredItemsPremium: number): number {
97	  return insuredItemsPremium * FIRST_INSURANCE_SURCHARGE_RATE;
98	}
99	
100	function roundInOfficesFavour(premium: number): number {
101	  return Math.ceil(premium);
102	}
103	
104	export function quote(customer: Customer, items: readonly Item[]): number {
105	  const insuredItemsPremium = insuredItemsPremiumOf(items);
106	  return roundInOfficesFavour(
107	    insuredItemsPremium + firstInsuranceSurchargeOn(insuredItemsPremium) + PROCESSING_FEE,
108	  );
109	}
