cp src/claim-office.ts /tmp/claim-office.trial-backup.ts && python3 - <<'EOF'
import re
p='src/claim-office.ts'
s=open(p).read()
old='''function itemSpecificSurchargesOn(item: Item, itemBasePremium: number): number {
  const curse = isCursed(item) ? itemBasePremium * CURSE_SURCHARGE_RATE : 0;
  const highEnchantment = isHighlyEnchanted(item)
    ? itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;
  return curse + highEnchantment;
}'''
new='''interface ItemRiskSurchargeRule {
  readonly appliesTo: (item: Item) => boolean;
  readonly rate: number;
}

const ITEM_RISK_SURCHARGE_RULES: readonly ItemRiskSurchargeRule[] = [
  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
];

function itemSpecificSurchargesOn(item: Item, itemBasePremium: number): number {
  return ITEM_RISK_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
    (sum, rule) => sum + itemBasePremium * rule.rate,
    0,
  );
}'''
assert old in s
open(p,'w').write(s.replace(old,new))
EOF
echo WROTE

